import React from 'react';
export const Dialog = ({ children, open }) => open ? <div className="fixed inset-0 bg-black/50 flex items-center justify-center">{children}</div> : null;
export const DialogContent = ({ children }) => <div className="bg-white p-6 rounded-lg max-w-md w-full">{children}</div>;
export const DialogHeader = ({ children }) => <div className="mb-4">{children}</div>;
export const DialogTitle = ({ children }) => <h2 className="text-xl font-bold">{children}</h2>;
export const DialogTrigger = ({ children }) => children;
